const items = $input.all();

return items.map((item, index) => {
  const j = item.json;

  const title = String(j.title || '').trim();
  const description = String(j.contentSnippet || j.content || j.description || '').trim();
  const url = String(j.link || '').trim();
  const date = j.isoDate || j.pubDate || new Date().toISOString();

  let source = 'External';

  if (url.includes('techcrunch.com')) source = 'TechCrunch';
  else if (url.includes('theverge.com')) source = 'The Verge';
  else if (url.includes('wired.com')) source = 'WIRED';
  else if (j.creator) source = String(j.creator);

  const image =
    j.enclosure?.url ||
    j.enclosure?.link ||
    j.image?.url ||
    'assets/images/pexels-jakubzerdzicki-38984817.jpg';

  return {
    json: {
      originalIndex: index,
      title,
      description,
      url,
      source,
      author: j.creator || 'External',
      published: new Date(date).toISOString(),
      image
    }
  };
});

const input = $input.first().json;

let existing = [];

try {
  if (input.content) {
    const decoded = Buffer.from(input.content, 'base64').toString('utf8');
    const parsed = JSON.parse(decoded);

    if (Array.isArray(parsed)) {
      existing = parsed;
    } else if (Array.isArray(parsed.articles)) {
      existing = parsed.articles;
    } else if (Array.isArray(parsed.data)) {
      existing = parsed.data;
    }
  }
} catch (error) {
  existing = [];
}

return [
  {
    json: {
      existingArticles: existing,
      currentSha: input.sha || '',
      githubPath: 'assets/data/blog-feed.json'
    }
  }
];

const existing = $json.existingArticles || [];

const existingUrls = new Set(
  existing
    .map(a => String(a.url || '').trim().toLowerCase())
    .filter(Boolean)
);

return [
  {
    json: {
      ...$json,
      existingUrls: Array.from(existingUrls)
    }
  }
];

const context = $input.first().json;
const existingUrls = new Set(context.existingUrls || []);
const existingArticles = context.existingArticles || [];
const sha = context.currentSha;

const allInputItems = $('Filter AI & Automation').all();

const newArticles = [];
const seen = new Set();

for (const item of allInputItems) {
  const article = item.json;
  const url = String(article.url || '').trim();
  const normalizedUrl = url.toLowerCase();

  if (!url) continue;
  if (existingUrls.has(normalizedUrl)) continue;
  if (seen.has(normalizedUrl)) continue;

  seen.add(normalizedUrl);
  newArticles.push(article);
}

return [
  {
    json: {
      existingArticles,
      currentSha: sha,
      newArticles,
      newArticleCount: newArticles.length
    }
  }
];

const data = $json;
const articles = data.newArticles || [];

return articles.map(article => ({
  json: {
    ...article,
    currentSha: data.currentSha,
    existingArticles: data.existingArticles
  }
}));

