const input = $input.first().json;
const original = $('Prepare New Articles').item.json;

let raw = '';

if (input.message?.content) raw = input.message.content;
else if (input.content) raw = input.content;
else if (typeof input.output === 'string') raw = input.output;
else raw = JSON.stringify(input);

raw = String(raw).trim();

raw = raw.replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/i, '').trim();

let ai;

try {
  ai = JSON.parse(raw);
} catch (error) {
  ai = {
    title: original.title,
    slug: original.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''),
    summary: original.description || original.title,
    business_takeaway: 'This technology development may create new opportunities for businesses adopting AI and automation.',
    category: 'AI & Automation',
    tags: ['AI', 'Automation', 'Technology'],
    target_keyword: 'AI automation',
    seo_title: original.title,
    seo_description: original.description || original.title
  };
}

const slug = String(ai.slug || ai.title || original.title)
  .toLowerCase()
  .replace(/[^a-z0-9]+/g, '-')
  .replace(/^-+|-+$/g, '')
  .slice(0, 90);

return [
  {
    json: {
      title: ai.title || original.title,
      slug,
      summary: ai.summary || original.description || original.title,
      business_takeaway: ai.business_takeaway || '',
      category: ai.category || 'AI & Automation',
      tags: Array.isArray(ai.tags) ? ai.tags.slice(0, 5) : ['AI', 'Automation'],
      target_keyword: ai.target_keyword || 'AI automation',
      seo_title: ai.seo_title || ai.title || original.title,
      seo_description: ai.seo_description || ai.summary || original.description,
      source: original.source,
      author: original.author,
      published: original.published,
      url: original.url,
      image: original.image,
      read_time: '4 min read',
      featured: false,
      tag_color: '#a0e2e1',
      tag_text: '#1f6463',
      currentSha: original.currentSha,
      existingArticles: original.existingArticles
    }
  }
];

const items = $input.all();

const validCategories = new Set([
  'AI & Automation',
  'Business Technology',
  'Cybersecurity',
  'Cloud',
  'Productivity',
  'Digital Transformation'
]);

return items
  .filter(item => {
    const a = item.json;
    return a.title && a.url && a.summary && a.slug;
  })
  .map(item => {
    const a = item.json;
    return {
      json: {
        ...a,
        category: validCategories.has(a.category) ? a.category : 'AI & Automation'
      }
    };
  });

const items = $input.all();

if (items.length === 0) {
  return [];
}

const existing = items[0].json.existingArticles || [];
const sha = items[0].json.currentSha || '';

const newArticles = items.map(i => {
  const a = { ...i.json };
  delete a.existingArticles;
  delete a.currentSha;
  return a;
});

const combined = [...newArticles, ...existing];

const unique = [];
const seen = new Set();

for (const article of combined) {
  const key = String(article.url || article.slug || '').toLowerCase();
  if (!key || seen.has(key)) continue;
  seen.add(key);
  unique.push(article);
}

unique.sort((a, b) => {
  return new Date(b.published || 0).getTime() - new Date(a.published || 0).getTime();
});

const latest = unique.slice(0, 50);

return [
  {
    json: {
      articles: latest,
      currentSha: sha,
      articleCount: latest.length
    }
  }
];

const data = $json;

return [
  {
    json: {
      githubPayload: {
        message: `Bobsave AI blog update — ${new Date().toISOString()}`,
        content: Buffer.from(JSON.stringify(data.articles, null, 2)).toString('base64'),
        sha: data.currentSha,
        branch: 'main'
      },
      articleCount: data.articleCount
    }
  }
];

return [
  {
    json: {
      status: 'success',
      message: 'Bobsave blog feed updated successfully.',
      updatedAt: new Date().toISOString(),
      githubFile: 'assets/data/blog-feed.json'
    }
  }
];
